import json
from docx import Document

with open('employee_data.json') as f:
    data=json.load(f)

reloc_yes = str(data.get('RELOCATION_PACKAGE','')).strip().lower() == 'yes'


def process_text(text):
    # handle conditional relocation block
    if '{{IF_RELOCATION}}' in text and '{{END_IF_RELOCATION}}' in text:
        start = text.index('{{IF_RELOCATION}}')
        end = text.index('{{END_IF_RELOCATION}}')
        inner = text[start+len('{{IF_RELOCATION}}'):end]
        if reloc_yes:
            text = text[:start] + inner + text[end+len('{{END_IF_RELOCATION}}'):]
        else:
            text = text[:start] + text[end+len('{{END_IF_RELOCATION}}'):]
    # replace placeholders
    for k,v in data.items():
        text = text.replace('{{'+k+'}}', str(v))
    return text


doc=Document('offer_letter_template.docx')

for p in doc.paragraphs:
    if '{{' in p.text:
        new_text = process_text(p.text)
        if new_text != p.text:
            p.text = new_text

for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                if '{{' in p.text:
                    new_text = process_text(p.text)
                    if new_text != p.text:
                        p.text = new_text

output = '/root/offer_letter_filled.docx'

doc.save(output)
print('saved', output)
